#!/usr/bin/env python3
import json
import re
import sys

TARGET = "192.168.1.4"

try:
    from framework_evidence import run_tool
except Exception as exc:
    print(json.dumps({"error": "Could not import framework_evidence.run_tool", "detail": str(exc)}))
    sys.exit(2)


def execute(label, argv):
    print(json.dumps({"check": label, "argv": argv}, sort_keys=True))
    try:
        result = run_tool(argv)
    except Exception as exc:
        result = {"status": "wrapper_error", "error": str(exc), "command": argv}
    print(json.dumps({"check": label, "tool_envelope": result}, sort_keys=True, default=str))
    return result


def raw_stdout(envelope):
    if not isinstance(envelope, dict):
        return ""
    runs = envelope.get("tool_runs")
    if isinstance(runs, list):
        return "\n".join(str(run.get("stdout", "")) for run in runs if isinstance(run, dict))
    return str(envelope.get("stdout", ""))


def open_tcp_ports(envelope, text):
    found = {}
    # Prefer structured observations when available.
    if isinstance(envelope, dict):
        runs = envelope.get("tool_runs", [])
        if isinstance(runs, list):
            for run in runs:
                if not isinstance(run, dict):
                    continue
                structured = run.get("structured_output")
                if not isinstance(structured, dict):
                    continue
                for host in structured.get("hosts", []) if isinstance(structured.get("hosts", []), list) else []:
                    if not isinstance(host, dict):
                        continue
                    for port in host.get("ports", []) if isinstance(host.get("ports", []), list) else []:
                        if not isinstance(port, dict) or str(port.get("protocol", "tcp")).lower() != "tcp":
                            continue
                        if str(port.get("state", "")).lower() != "open":
                            continue
                        try:
                            number = int(port.get("port"))
                        except (TypeError, ValueError):
                            continue
                        found[number] = str(port.get("reported_label") or port.get("service") or "")
    # Preserve discoverable open-port coverage if the structured parser is absent.
    for match in re.finditer(r"^\s*(\d+)/tcp\s+open\s+(\S+)", text, re.MULTILINE):
        found.setdefault(int(match.group(1)), match.group(2))
    return found


scan = execute("full_tcp_service_inventory", [
    "nmap", "-Pn", "-n", "-T4", "-p-", "-sV", "--reason", TARGET
])
scan_text = raw_stdout(scan)
ports = open_tcp_ports(scan, scan_text)
print(json.dumps({
    "assessment": "TCP inventory parsed from observed output; this is not an identity or access-success claim.",
    "target": TARGET,
    "open_tcp_ports": [{"port": p, "reported_service": ports[p]} for p in sorted(ports)],
    "scan_output_available": bool(scan_text),
    "coverage_note": "A missing or unparsed result is not evidence that services are absent. Nmap output and parser status are retained above."
}, sort_keys=True))

scripts = []
if any("http" in label.lower() or "https" in label.lower() for label in ports.values()) or any(
    re.search(r"\b(http|https)\b", line, re.I) for line in scan_text.splitlines()
):
    scripts.extend(["http-title", "http-headers"])
if any("ftp" in label.lower() for label in ports.values()) or re.search(r"\bftp\b", scan_text, re.I):
    scripts.append("ftp-anon")
if any(label.lower() in ("microsoft-ds", "netbios-ssn", "smb") or "smb" in label.lower() for label in ports.values()) or re.search(r"\bsmb\b", scan_text, re.I):
    scripts.extend(["smb-os-discovery", "smb-enum-shares"])

if scripts and ports:
    # NSE scripts here identify service metadata or test for publicly accessible material;
    # they do not guess passwords or attempt an exploit.
    execute("observed_service_safe_enumeration", [
        "nmap", "-Pn", "-n", "-sV", "-p", ",".join(str(p) for p in sorted(ports)),
        "--script", ",".join(dict.fromkeys(scripts)), TARGET
    ])

for port, label in sorted(ports.items()):
    service_hint = label.lower()
    if "http" in service_hint or "https" in service_hint or port in (80, 443, 8000, 8008, 8080, 8443):
        tls = "https" in service_hint or port in (443, 8443)
        url = f"{'https' if tls else 'http'}://{TARGET}:{port}/"
        argv = ["curl", "-sS", "-i", "--max-time", "12", "--max-filesize", "1048576"]
        if tls:
            argv.append("-k")
        argv.append(url)
        execute(f"observed_web_root_port_{port}", argv)
    elif "ftp" in service_hint or port == 21:
        # Request a directory listing using the client's anonymous default only;
        # no candidate or guessed user password is supplied.
        execute(f"observed_ftp_listing_port_{port}", [
            "curl", "-sS", "--list-only", "--max-time", "12", f"ftp://{TARGET}:{port}/"
        ])

print(json.dumps({
    "route_assessment_limits": [
        "A service label or banner is not proof of an applicable vulnerability or a student session.",
        "No exploit module was run and no credentials were guessed or brute-forced.",
        "If an observed product/version suggests a vulnerability route, compare that evidence with an applicable module before any separate authorized test.",
        "Any accessible material must be reviewed as evidence; only discovered, valid student authentication material should be tested, and only against this target.",
        "A session requires effective-identity evidence; inventory or an accessible anonymous listing alone does not establish student access."
    ]
}, sort_keys=True))

