import datetime
import json
import socket
import struct

TARGET = ("192.168.1.4", 520)
TIMEOUT_SECONDS = 2.0


def utc_now():
    return datetime.datetime.now(datetime.timezone.utc).isoformat()


def make_request(version):
    # RIP request for the complete routing table: AFI 0 and metric 16.
    header = struct.pack("!BBH", 1, version, 0)
    route_entry = struct.pack("!HHIIII", 0, 0, 0, 0, 0, 16)
    return header + route_entry


def decode_datagram(data):
    decoded = {"length": len(data), "raw_hex": data.hex()}
    if len(data) < 4:
        decoded["decode_note"] = "Shorter than a RIP header"
        return decoded

    command, version, zero = struct.unpack("!BBH", data[:4])
    decoded["header"] = {"command": command, "version": version, "zero": zero}
    if command == 2:
        decoded["command_name"] = "response"
    elif command == 1:
        decoded["command_name"] = "request"
    else:
        decoded["command_name"] = "unknown"

    entries = []
    offset = 4
    while offset + 20 <= len(data):
        afi, route_tag, address, mask, next_hop, metric = struct.unpack(
            "!HHIIII", data[offset:offset + 20]
        )
        entries.append({
            "afi": afi,
            "route_tag": route_tag,
            "address": socket.inet_ntoa(struct.pack("!I", address)),
            "mask": socket.inet_ntoa(struct.pack("!I", mask)),
            "next_hop": socket.inet_ntoa(struct.pack("!I", next_hop)),
            "metric": metric,
        })
        offset += 20
    decoded["entries"] = entries
    if offset < len(data):
        decoded["trailing_bytes_hex"] = data[offset:].hex()
    if command == 2 and version == 1 and len(data) >= 6:
        decoded["response_error_code"] = struct.unpack("!H", data[4:6])[0]
    return decoded


def probe_version(version):
    request = make_request(version)
    result = {
        "version_requested": version,
        "destination": {"ip": TARGET[0], "port": TARGET[1]},
        "request_hex": request.hex(),
        "request_length": len(request),
        "request_format": "RIP complete-table request (AFI 0, metric 16)",
        "started_at": utc_now(),
        "responses": [],
        "timeout_seconds": TIMEOUT_SECONDS,
    }
    sock = None
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        sock.settimeout(TIMEOUT_SECONDS)
        sent = sock.sendto(request, TARGET)
        result["bytes_sent"] = sent
        result["sent_at"] = utc_now()
        while True:
            try:
                data, source = sock.recvfrom(65535)
                result["responses"].append({
                    "received_at": utc_now(),
                    "source": {"ip": source[0], "port": source[1]},
                    "decoded": decode_datagram(data),
                })
            except socket.timeout:
                result["receive_timeout"] = True
                result["outcome"] = (
                    "responses_received_then_receive_window_expired"
                    if result["responses"] else "no_response_before_timeout"
                )
                break
    except OSError as exc:
        result["outcome"] = "socket_error"
        result["socket_error"] = {"type": type(exc).__name__, "message": str(exc)}
    finally:
        if sock is not None:
            sock.close()
    result["finished_at"] = utc_now()
    return result


def main():
    report = {
        "purpose": "Read-only RIP protocol probes to the specified endpoint; no route changes or credential attempts.",
        "probes": [probe_version(1), probe_version(2)],
        "coverage_note": "One complete-table request was sent for each RIP version. A timeout is only a lack of response during that probe's receive window; it does not establish service absence.",
    }
    print(json.dumps(report, sort_keys=True))


if __name__ == "__main__":
    main()

