import json
import sys

try:
    from framework_evidence import run_tool
except Exception as exc:
    print(json.dumps({"error": "could_not_import_framework_evidence", "detail": str(exc)}), flush=True)
    raise

TARGET = "192.168.1.4"
CHUNK_SIZE = 512
completed_ranges = []
attempted_ranges = []
failed_ranges = []


def tool_runs(envelope):
    if isinstance(envelope, dict):
        runs = envelope.get("tool_runs")
        if isinstance(runs, list):
            return runs
    return []


def confirmed_complete(envelope):
    runs = tool_runs(envelope)
    if not runs:
        return False
    for run in runs:
        if not isinstance(run, dict) or run.get("exit_code") != 0:
            return False
        parsed = run.get("structured_output")
        if not isinstance(parsed, dict) or parsed.get("scan_completed") is not True:
            return False
    return True

for start in range(1, 65536, CHUNK_SIZE):
    end = min(start + CHUNK_SIZE - 1, 65535)
    port_range = f"{start}-{end}"
    argv = [
        "nmap", "-Pn", "-n", "-sU", "-sV", "--version-light", "-T4",
        "--max-retries", "2", "--host-timeout", "45s",
        "-p", port_range, TARGET,
    ]
    attempted_ranges.append(port_range)
    print(json.dumps({"record": "range_start", "range": port_range, "command": argv}), flush=True)
    try:
        envelope = run_tool(argv)
        # Preserve and emit the complete returned envelope, including raw streams
        # and structured observations, for this independently invoked range.
        print(json.dumps({"range": port_range, "tool_envelope": envelope}, default=str), flush=True)
        if confirmed_complete(envelope):
            completed_ranges.append(port_range)
        else:
            failed_ranges.append({"range": port_range, "reason": "completion_not_confirmed_by_exit_code_and_parsed_scan_status"})
    except Exception as exc:
        failed_ranges.append({"range": port_range, "reason": "run_tool_exception", "detail": str(exc)})
        print(json.dumps({"range": port_range, "error": "run_tool_exception", "detail": str(exc)}), flush=True)
        # A wrapper-level exception may indicate the invocation path is unavailable;
        # stop rather than issuing many identical calls without usable evidence.
        break

not_attempted = []
if attempted_ranges:
    last_end = int(attempted_ranges[-1].split("-")[1])
    if last_end < 65535:
        not_attempted.append(f"{last_end + 1}-65535")
else:
    not_attempted.append("1-65535")

print(json.dumps({
    "record": "coverage_summary",
    "target": TARGET,
    "requested_range": "1-65535",
    "chunk_size": CHUNK_SIZE,
    "attempted_ranges": attempted_ranges,
    "confirmed_complete_ranges": completed_ranges,
    "ranges_without_confirmed_completion": failed_ranges,
    "not_attempted_ranges": not_attempted,
    "full_range_coverage_established": len(completed_ranges) == 129 and not failed_ranges and not not_attempted,
    "interpretation": "Only ranges with exit code 0 and parsed scan_completed=true are counted as confirmed complete; unresponsive or filtered UDP ports are not asserted absent."
}, default=str), flush=True)

