import json
from pathlib import Path

ARCHIVE_LOCATOR = "llm_inputs/bb9ea469c440e503076cab37f74f7edafba2703ead4ffd9a8c48251bf8582d29.json"
GENERATED_ROOT = "/root/scripts"
MATERIAL_KEYS = {"supplied_materials", "user_supplied_artifacts", "task_provided_materials", "artifacts"}


def is_generated(value):
    text = str(value)
    return text == GENERATED_ROOT or text.startswith(GENERATED_ROOT + "/")


def collect_records(value, location="$", found=None):
    if found is None:
        found = []
    if isinstance(value, dict):
        for key, child in value.items():
            child_location = location + "." + str(key)
            if str(key).lower() in MATERIAL_KEYS:
                found.append({"record_location": child_location, "record": child})
            collect_records(child, child_location, found)
    elif isinstance(value, list):
        for index, child in enumerate(value):
            collect_records(child, location + "[" + str(index) + "]", found)
    return found


def summarize_record(record, record_location):
    items = record if isinstance(record, list) else [record]
    summaries = []
    for item in items:
        if isinstance(item, dict):
            path_value = item.get("path", item.get("source_path", item.get("filename")))
            provenance = item.get("provenance", item.get("origin", item.get("source")))
            if path_value is not None and is_generated(path_value):
                continue
            summaries.append({
                "source_path": path_value,
                "provenance": provenance,
                "record_location": record_location,
                "value_printed": False,
            })
        elif isinstance(item, str):
            if is_generated(item):
                continue
            summaries.append({
                "source_path": item,
                "provenance": "explicitly listed in the archived input record",
                "record_location": record_location,
                "value_printed": False,
            })
        else:
            summaries.append({
                "record_location": record_location,
                "record_type": type(item).__name__,
                "value_printed": False,
            })
    return summaries


result = {
    "purpose": "Inventory explicitly identified task-supplied materials only; no unrelated filesystem search performed.",
    "context_records": [
        {
            "source_path": ARCHIVE_LOCATOR,
            "provenance": "original_input artifact identified in supplied context; marked available_in_archive",
            "archive_availability": "reported by supplied context; not independently verified",
        },
        {
            "source_path": GENERATED_ROOT,
            "provenance": "identified in supplied material_provenance as generated experiment/task actions",
            "classification": "excluded",
        },
    ],
    "direct_access_check": {},
    "explicit_material_records": [],
    "coverage_limitations": [],
}

candidate = Path(ARCHIVE_LOCATOR)
try:
    resolved = candidate.resolve(strict=False)
    if candidate.is_file():
        result["direct_access_check"] = {
            "source_path": str(resolved),
            "status": "accessible at the exact supplied relative locator",
        }
        try:
            with candidate.open("r", encoding="utf-8") as stream:
                archived_input = json.load(stream)
            records = collect_records(archived_input)
            for entry in records:
                result["explicit_material_records"].extend(
                    summarize_record(entry["record"], entry["record_location"])
                )
            if not records:
                result["coverage_limitations"].append(
                    "The accessible archived input contained no recognized explicit material-list fields."
                )
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            result["coverage_limitations"].append(
                "The exact archive path exists but could not be parsed: " + type(exc).__name__ + ": " + str(exc)
            )
    else:
        result["direct_access_check"] = {
            "source_path": str(resolved),
            "status": "not accessible as a file at the exact supplied relative locator",
        }
        result["coverage_limitations"].append(
            "No other filesystem locations were searched; archive availability is known only from the supplied context."
        )
except OSError as exc:
    result["direct_access_check"] = {"status": "access check failed"}
    result["coverage_limitations"].append(type(exc).__name__ + ": " + str(exc))

print(json.dumps(result, ensure_ascii=False, sort_keys=True))

