import hashlib
import json
import os
from pathlib import Path

ARTIFACT = "llm_inputs/bb9ea469c440e503076cab37f74f7edafba2703ead4ffd9a8c48251bf8582d29.json"
PREVIOUSLY_UNAVAILABLE = Path("/root/scripts") / ARTIFACT


def check(label, candidate):
    result = {"source": label, "path": str(candidate)}
    try:
        resolved = candidate.resolve(strict=True)
        if not resolved.is_file():
            result.update(status="not_a_file", resolved_path=str(resolved))
            return result
        data = resolved.read_bytes()
        result.update(
            status="readable",
            resolved_path=str(resolved),
            bytes_read=len(data),
            sha256=hashlib.sha256(data).hexdigest(),
        )
    except FileNotFoundError as exc:
        result.update(status="not_found", error=str(exc))
    except PermissionError as exc:
        result.update(status="permission_denied", error=str(exc))
    except OSError as exc:
        result.update(status="access_error", error=f"{type(exc).__name__}: {exc}")
    return result


results = []
relative_candidate = Path(ARTIFACT)
try:
    same_as_previous = relative_candidate.resolve() == PREVIOUSLY_UNAVAILABLE.resolve()
except OSError:
    same_as_previous = False
if same_as_previous:
    results.append({
        "source": "working_directory_relative_path",
        "path": str(relative_candidate),
        "status": "skipped",
        "reason": "resolves to the previously reported unavailable /root/scripts artifact path",
    })
else:
    results.append(check("working_directory_relative_path", relative_candidate))

# Only explicit runtime environment entries naming an archive or artifact store
# are treated as possible archive roots. Probe the exact supplied relative path;
# do not enumerate or search directory contents.
seen = set()
for key, value in sorted(os.environ.items()):
    normalized = key.lower()
    if not ("archive" in normalized or "artifact_store" in normalized):
        continue
    if not value:
        results.append({"source": f"environment:{key}", "status": "empty_root"})
        continue
    root = Path(value).expanduser()
    candidate = root / ARTIFACT
    try:
        resolved_candidate = candidate.resolve()
    except OSError:
        resolved_candidate = candidate
    identity = str(resolved_candidate)
    if identity in seen:
        continue
    seen.add(identity)
    if resolved_candidate == PREVIOUSLY_UNAVAILABLE.resolve():
        results.append({
            "source": f"environment:{key}",
            "path": str(candidate),
            "status": "skipped",
            "reason": "resolves to the previously reported unavailable /root/scripts artifact path",
        })
        continue
    results.append(check(f"environment:{key}", candidate))

usable = [item for item in results if item.get("status") == "readable"]
print(json.dumps({
    "artifact_identifier": ARTIFACT,
    "reported_archive_availability": "supplied provenance record only; not independent verification",
    "lookup_scope": "exact artifact path under working directory and explicit archive/artifact-store environment roots only; no recursive search",
    "archive_access_verified": bool(usable),
    "results": results,
}, sort_keys=True))
